{
  "settings": [
    {
      "name": "secret_directory",
      "input_type": "VARCHAR",
      "scope": "LOCAL",
      "evidence": "To change the secrets directory, issue:\n\n```sql\nSET secret_directory = 'path/to/my_secrets_dir';\n```\n\nThe `secret_directory` setting applies to the current DuckDB instance and is not persisted across DuckDB instances. If you use a custom secrets directory, set `secret_directory` again when starting a new DuckDB instance before creating or using persistent secrets from that directory.",
      "default_kind": "literal",
      "default_value": "~/.duckdb/stored_secrets",
      "default_evidence": "By default, this will write the secret (unencrypted) to the `~/.duckdb/stored_secrets` directory."
    },
    {
      "name": "home_directory",
      "input_type": "VARCHAR",
      "scope": "GLOBAL",
      "evidence": "Note that setting the value of the `home_directory` configuration option has no effect on the location of the secrets.",
      "default_kind": "absent",
      "default_value": null,
      "default_evidence": null
    }
  ]
}
